<template>
<section class="stock-results-simple" aria-label="Stock analysis results">
  <div class="results-topline"><p>One-year outlook<span v-if="run.verdict?.evidence_strength"> · {{ run.verdict.evidence_strength }} evidence</span></p><span>{{ assessmentLabel }}</span></div>
  <div class="stock-results-primary" :class="{'no-rating':!rating.total}"><StockProjection v-if="forecast.available" :run="run"/><div v-else class="qualitative-outlook"><h2>The company outlook</h2><p><StockEvidenceText :text="run.one_year?.arguments?.for?.thesis||run.verdict?.business_assessment||run.verdict?.summary||''" :sources="sources"/></p><StockPriceContext :run="run"/></div><StockAgentRating v-if="rating.total" :run="run"/></div>
  <div class="stock-reasoning-layout"><section v-if="reasoning.growth||reasoning.opportunities.length"><h2>Reasoning</h2><h3>Why this stock could grow</h3><p v-if="reasoning.growth"><StockEvidenceText :text="reasoning.growth" :sources="sources"/></p><div v-if="reasoning.opportunities.length" class="stock-opportunities"><span v-for="opportunity in reasoning.opportunities.slice(0,3)" :key="opportunity.id">{{ opportunity.name }}</span></div></section><section v-if="reasoning.supporting.length"><h2>What supports the outlook</h2><ol><li v-for="(claim,index) in reasoning.supporting.slice(0,2)" :key="index"><span>{{ index+1 }}</span><div><StockEvidenceText :text="claim.text" :sources="sources"/><div class="claim-citations"><a v-for="id in claim.evidence_ids.filter(id=>source(id)?.url)" :key="id" :href="source(id).url" target="_blank" rel="noopener noreferrer">{{ source(id).title }}<ResearchIcon name="external"/></a></div></div></li></ol></section></div>
  <button class="stock-discussion-link" @click="$emit('analysis')">See how the agents reached this view<ResearchIcon name="arrow"/></button>
  <details class="stock-results-details"><summary>Research details</summary><div><slot name="details"/><details v-if="run.verdict?.opposing?.length"><summary>What could change the outlook</summary><p v-for="(claim,index) in run.verdict.opposing" :key="index"><StockEvidenceText :text="claim.text" :sources="sources"/></p></details><div class="detail-links"><button @click="$emit('research')">Company research</button><button @click="$emit('annual')">One-year debate & assumptions</button><button @click="$emit('investors')">Investor decisions</button><button @click="$emit('sources')">Sources</button><button @click="$emit('download')">Export report</button></div></div></details>
  <p class="stock-results-note">{{ forecast.available?'Conditional one-year scenarios · saved research':'Saved company research' }} · simulated investors.</p>
</section>
</template>
<script setup>
import {computed} from 'vue'
import StockProjection from './StockProjection.vue'
import StockAgentRating from './StockAgentRating.vue'
import StockEvidenceText from './StockEvidenceText.vue'
import StockPriceContext from './StockPriceContext.vue'
import ResearchIcon from './ResearchIcon.vue'
import {stockProjection,stockAgentRating,stockReasoning} from '../utils/stockResultsView.mjs'
const props=defineProps({run:{type:Object,required:true}})
defineEmits(['analysis','research','annual','investors','sources','download'])
const forecast=computed(()=>stockProjection(props.run)),rating=computed(()=>stockAgentRating(props.run)),reasoning=computed(()=>stockReasoning(props.run))
const sources=computed(()=>Array.isArray(props.run.dossier?.sources)?props.run.dossier.sources:[])
const source=id=>sources.value.find(s=>s.id===id)
const assessmentLabel=computed(()=>({attractive:'Attractive in the saved assessment',watch:'Watch',avoid:'Avoid in the saved assessment',insufficient_evidence:'Evidence limited'}[props.run.verdict?.verdict]||'Saved assessment'))
</script>
